mapper.select:
UPDATE referrals SET status = 'REWARDED', rewarded_at = #{now}
WHERE friend_id = #{friendId} AND status = 'PENDING' AND expires_at > #{now}
RETURNING id, referrer_id

mapper.sql:
WITH r AS (
    SELECT id, referrer_id, friend_id FROM referrals
    WHERE created_at >= #{from} AND created_at < #{to}
),
v AS (
    SELECT s.customer_id, count(*) AS visits, count(DISTINCT s.local_date) AS days
    FROM stamps s JOIN r ON r.friend_id = s.customer_id
    WHERE s.source = 'NFC_TAP' AND s.status = 'CONFIRMED'
    AND s.branch_id = #{branchId}
    GROUP BY s.customer_id
)
